UPDATE cs
SET cs.bitmapHasSynced = dbo.f_GenerateProductStatus (cs.bitmapHasSynced,@BitOrder,0)
FROM custProductStatus cs WITH (ROWLOCK,UPDLOCK)
	INNER JOIN #ListCust l ON cs.custid = l.custid